return (function()
  local s = ""
  local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
  local lookup = {}
  for i = 1, #alphabet do lookup[alphabet:sub(i, i)] = i - 1 end
  local buffer, bits, out = 0, 0, {}
  for i = 1, #s do
    local c = s:sub(i, i)
    local v = lookup[c]
    if v ~= nil then
      buffer, bits = buffer * 64 + v, bits + 6
      if bits >= 8 then
        bits = bits - 8
        out[#out + 1] = string.char(math.floor(buffer / 2 ^ bits) % 256)
        buffer = buffer % 2 ^ bits
      end
    elseif c ~= "=" then
      error("VP:loader", 0)
    end
  end
  local ld = loadstring or load
  if type(ld) ~= "function" then error("VP:ld", 0) end
  local fn, err = ld(table.concat(out))
  s, out = nil, nil
  if type(fn) ~= "function" then error("VP:c " .. tostring(err), 0) end
  return fn()
end)()
